F.e('kc',r'K_c=\frac{[\mathrm{NO}]^2}{[\mathrm{N_2}][\mathrm{O_2}]}','K_c = [NO]² / [N₂][O₂]')
F.p('b2','b3','h2','c1')
F.e('cn',r'C=\frac{n}{V}=\frac{P}{RT}','C = n/V = P/RT')
